# -*- coding: utf-8 -*-
"""Destinazioni candidate per agosto 2027 (fuori Europa) con clima di agosto e motivazione.
tab: "new" = paese mai visitato (tab principale) | "vis" = paese gia' visitato, giro nuovo (seconda tab)
g (giudizio clima): ottimo | buono | accettabile | sconsigliato
scan: "full" = tutte le combinazioni data x durata 10/11/12 | "light" = solo durata 11 (clima proibitivo, solo prezzo indicativo)
"""

def D(code, city, country, area, tab, temp, rain, g, why, seen=None, giro=None, flag=None, scan="full"):
    return {"code": code, "city": city, "country": country, "area": area, "tab": tab, "temp": temp, "rain": rain,
            "g": g, "why": why, "seen": seen, "giro": giro, "flag": flag, "scan": scan}

